def solve(tables: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    # Plan:
    # - Input: input_01.csv only; ignore input_02.csv.
    # - Convert Games Roman numeral to integer game number.
    # - Compute Year = 1896 + (game_number - 1) * 4.
    # - Parse Dates into Start/End strings; handle day-only start using end month.
    # - Cast Nations, Sports, Events to nullable integers.
    # - Drop rows where Start Date or End Date parsing failed.
    # - Keep only columns: Start Date, End Date, Games, Host, Nations, Sports, Events.
    # - Return {"output_01.csv": cleaned_df}.

    import re

    # Helper: Roman numeral to integer
    def roman_to_int(roman: str) -> int:
        roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        total = 0
        prev = 0
        for ch in reversed(roman.upper()):
            curr = roman_map.get(ch, 0)
            if curr < prev:
                total -= curr
            else:
                total += curr
            prev = curr
        return total

    # Helper: Parse Dates column into Start/End date strings (M/D/YYYY)
    def parse_date_range(dates_str, year):
        if pd.isnull(dates_str):
            return (None, None)
        # Split on en dash or hyphen (allow spaces around)
        parts = re.split(r'[–-]', dates_str, maxsplit=1)
        if len(parts) != 2:
            return (None, None)
        start_str, end_str = parts[0].strip(), parts[1].strip()

        month_map = {
            'january': 1, 'february': 2, 'march': 3, 'april': 4,
            'may': 5, 'june': 6, 'july': 7, 'august': 8,
            'september': 9, 'october': 10, 'november': 11, 'december': 12
        }

        # Parse end part (day month)
        end_tokens = end_str.split()
        if len(end_tokens) != 2:
            return (None, None)
        try:
            end_day = int(end_tokens[0])
            end_month = month_map.get(end_tokens[1].lower())
            if end_month is None:
                return (None, None)
        except Exception:
            return (None, None)

        # Parse start part
        start_tokens = start_str.split()
        if len(start_tokens) == 1:
            # day only, use end month
            try:
                start_day = int(start_tokens[0])
                start_month = end_month
            except Exception:
                return (None, None)
        elif len(start_tokens) == 2:
            try:
                start_day = int(start_tokens[0])
                start_month = month_map.get(start_tokens[1].lower())
                if start_month is None:
                    return (None, None)
            except Exception:
                return (None, None)
        else:
            return (None, None)

        # Build M/D/YYYY strings
        start_date_str = f"{start_month}/{start_day}/{year}"
        end_date_str = f"{end_month}/{end_day}/{year}"
        return (start_date_str, end_date_str)

    # Load the main input
    df = tables["input_01.csv"].copy()

    # Convert Roman numerals to game numbers and compute Year
    df["Game_Number"] = df["Games"].apply(roman_to_int)
    df["Year"] = 1896 + (df["Game_Number"] - 1) * 4

    # Parse Dates into Start/End date strings
    df[["Start Date", "End Date"]] = df.apply(
        lambda row: parse_date_range(row["Dates"], row["Year"]),
        axis=1,
        result_type="expand"
    )

    # Ensure numeric count fields are nullable integers
    df["Nations"] = pd.to_numeric(df["Nations"], errors="coerce").astype("Int64")
    df["Sports"] = pd.to_numeric(df["Sports"], errors="coerce").astype("Int64")
    df["Events"] = pd.to_numeric(df["Events"], errors="coerce").astype("Int64")

    # Drop rows where date parsing failed
    df = df.dropna(subset=["Start Date", "End Date"])

    # Keep only required columns in the specified order
    out_df = df[["Start Date", "End Date", "Games", "Host", "Nations", "Sports", "Events"]]

    return {"output_01.csv": out_df}

def solve(tables: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    # Plan:
    # - Map filenames to Regions (London, Northern, Scotland, Wales).
    # - For each DataFrame, extract month abbreviations from row 1.
    # - For each data row (from row 3), extract Sales/Profit per month.
    # - Convert values to numeric, create Date as 01/MM/2022.
    # - Concatenate all rows into a single output DataFrame with columns Region, Store, Date, Sales, Profit.
    region_map = {
        "input_01.csv": "London",
        "input_02.csv": "Northern",
        "input_03.csv": "Scotland",
        "input_04.csv": "Wales"
    }
    month_map = {
        "Jan": "01", "Feb": "02", "Mar": "03", "Apr": "04",
        "May": "05", "Jun": "06", "Jul": "07", "Aug": "08",
        "Sep": "09", "Oct": "10", "Nov": "11", "Dec": "12"
    }
    results = []
    for filename, df in tables.items():
        region = region_map.get(filename)
        if region is None:
            continue
        month_row = df.iloc[1, :]
        month_cols = []
        for col_idx in range(len(month_row)):
            val = month_row.iloc[col_idx]
            if pd.isna(val):
                continue
            val_str = str(val).strip().title()
            if val_str in month_map:
                month_cols.append((val_str, month_map[val_str], col_idx))
        if not month_cols:
            continue
        for row_idx in range(3, len(df)):
            store = df.iloc[row_idx, 0]
            if pd.isna(store) or str(store).strip() == "":
                continue
            store_str = str(store).strip()
            for month_abbr, month_num, sales_col_idx in month_cols:
                profit_col_idx = sales_col_idx + 1
                sales_val = df.iloc[row_idx, sales_col_idx]
                profit_val = df.iloc[row_idx, profit_col_idx]
                sales_num = pd.to_numeric(sales_val, errors='coerce')
                profit_num = pd.to_numeric(profit_val, errors='coerce')
                date_str = f"01/{month_num}/2022"
                results.append({
                    "Region": region,
                    "Store": store_str,
                    "Date": date_str,
                    "Sales": sales_num,
                    "Profit": profit_num
                })
    output_df = pd.DataFrame(results)
    output_df = output_df[["Region", "Store", "Date", "Sales", "Profit"]]
    return {"output_01.csv": output_df}
